<template>
	<!--
	  Foto serah terima BSTK sebagai satu kartu collapsible — pola yang sama
	  dengan kartu unit di Request AYDA (AydaUnitCards). Di desk bentuknya tabel
	  grid; di portal tabel terlalu sempit untuk layar ponsel, jadi isinya
	  dijadikan daftar di dalam collapse.
	-->
	<div class="overflow-hidden rounded-2xl border border-ui-line-gray-200 bg-ui-surface shadow-sm">
		<!-- Header (klik untuk buka/tutup) -->
		<button
			type="button"
			class="foto-lihat flex w-full items-center gap-3 px-4 py-3 text-left"
			@click="open = !open"
		>
			<span
				class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5"
					fill="none"
					stroke="currentColor"
					stroke-width="1.8"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<rect width="18" height="14" x="3" y="6" rx="2" />
					<circle cx="12" cy="13" r="3" />
					<path d="M8 6l1.5-2h5L16 6" />
				</svg>
			</span>
			<span class="min-w-0 flex-1">
				<span class="block truncate text-sm font-semibold text-ui-ink-gray-900">
					Foto Unit &amp; Dokumen
				</span>
				<span class="block truncate text-xs text-ui-ink-gray-400">
					{{ ringkasan }}
				</span>
			</span>
			<svg
				xmlns="http://www.w3.org/2000/svg"
				viewBox="0 0 24 24"
				class="h-5 w-5 shrink-0 text-ui-ink-gray-400 transition-transform"
				:class="{ 'rotate-180': open }"
				fill="none"
				stroke="currentColor"
				stroke-width="2"
				stroke-linecap="round"
				stroke-linejoin="round"
			>
				<path d="m6 9 6 6 6-6" />
			</svg>
		</button>

		<!-- Isi: satu baris per slot foto -->
		<div v-if="open" class="border-t border-ui-line-gray-100 px-4 py-3">
			<p v-if="!editable && !terisi.length" class="py-3 text-center text-xs text-ui-ink-gray-400">
				Belum ada foto.
			</p>

			<ul v-else class="divide-y divide-ui-line-gray-100">
				<li v-for="slot in barisTampil" :key="slot.jenis_foto" class="py-2.5">
					<div class="flex items-center gap-3">
						<!-- Thumbnail = tombol lihat. Di mode isi, tombol Pilih/Ganti
						     di kanan yang mengganti fotonya, jadi klik di gambar
						     tidak pernah berarti dua hal. -->
						<button
							v-if="slot.foto"
							type="button"
							class="foto-lihat shrink-0 overflow-hidden rounded-lg border-0 bg-transparent p-0"
							:title="`Lihat ${slot.jenis_foto}`"
							@click="lihat(slot)"
						>
							<img
								:src="slot.foto"
								:alt="slot.jenis_foto"
								class="h-12 w-12 object-cover"
							/>
						</button>
						<span
							v-else
							class="flex h-12 w-12 shrink-0 items-center justify-center rounded-lg border border-dashed border-ui-line-gray-300 text-ui-ink-gray-300"
						>
							<svg
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-5 w-5"
								fill="none"
								stroke="currentColor"
								stroke-width="1.8"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<rect width="18" height="18" x="3" y="3" rx="2" />
								<path d="m3 16 5-5 4 4 3-3 6 6" />
							</svg>
						</span>

						<component
							:is="slot.foto ? 'button' : 'span'"
							:type="slot.foto ? 'button' : null"
							class="foto-lihat min-w-0 flex-1 border-0 bg-transparent p-0 text-left"
							@click="slot.foto && lihat(slot)"
						>
							<span class="block truncate text-sm font-medium text-ui-ink-gray-800">
								{{ slot.jenis_foto }}
							</span>
							<span
								class="block truncate text-xs"
								:class="slot.foto ? 'text-ui-ink-green-600' : 'text-ui-ink-gray-400'"
							>
								{{ slot.foto ? 'Sudah ada' : 'Belum ada' }}
							</span>
						</component>

						<template v-if="editable">
							<button
								v-if="slot.foto"
								type="button"
								class="shrink-0 rounded-full px-2 py-1 text-xs font-medium text-ui-ink-red-600 transition hover:bg-ui-surface-red-50"
								:disabled="uploading"
								@click="hapus(slot.jenis_foto)"
							>
								Hapus
							</button>
							<button
								type="button"
								class="shrink-0 rounded-full border border-primary px-3 py-1.5 text-xs font-semibold text-primary transition hover:bg-primary/5 disabled:opacity-50"
								:disabled="uploading"
								@click="pilih(slot.jenis_foto)"
							>
								{{
									uploadingJenis === slot.jenis_foto
										? 'Mengunggah…'
										: slot.foto
											? 'Ganti'
											: 'Pilih'
								}}
							</button>
						</template>
					</div>
				</li>
			</ul>
		</div>

		<input
			v-if="editable"
			ref="fileInput"
			type="file"
			accept="image/*"
			class="hidden"
			@change="onFileChange"
		/>
	</div>
</template>

<script setup>
import { computed, ref } from 'vue'
// Sama dengan lampiran di Data Pengajuan: gambar dibuka lewat viewer in-app
// (di native `window.open` akan lompat ke browser luar dan URL /files relatif
// tidak valid di origin lokal).
import { openAttachment } from '../composables/pdfViewer'

// Urutan & nama slot HARUS sama dengan FOTO_BSTK_JENIS di
// juragan/collection/doctype/bstk/bstk.py — server membuang jenis di luar daftar.
const JENIS = [
	'Foto Unit (Sisi Depan)',
	'Foto Unit (Sisi Belakang)',
	'Foto Unit (Sisi Kiri)',
	'Foto Unit (Sisi Kanan)',
	'Foto BSTK',
	'Foto STNK',
	'Foto No Rangka',
	'Foto No Mesin',
]
// Data historis tetap tampil sebelum patch migrasi dijalankan di suatu site.
const JENIS_LEGACY = {
	'Foto BSTK Depan': 'Foto Unit (Sisi Depan)',
	'Foto BSTK Belakang': 'Foto Unit (Sisi Belakang)',
	'Foto BSTK Kiri': 'Foto Unit (Sisi Kiri)',
	'Foto BSTK Kanan': 'Foto Unit (Sisi Kanan)',
	STNK: 'Foto STNK',
	'No Rangka': 'Foto No Rangka',
	'No Mesin': 'Foto No Mesin',
}
const MAX_MB = 5

const props = defineProps({
	modelValue: { type: Array, default: () => [] },
	editable: { type: Boolean, default: false },
	nomorBstk: { type: String, default: '' },
	defaultOpen: { type: Boolean, default: false },
})
const emit = defineEmits(['update:modelValue', 'error'])

const open = ref(props.defaultOpen)
const fileInput = ref(null)
const uploadingJenis = ref('')
const uploading = computed(() => !!uploadingJenis.value)

const fotoByJenis = computed(() => {
	const map = {}
	for (const row of props.modelValue || []) {
		if (row && row.jenis_foto && row.foto) {
			const jenis = JENIS_LEGACY[row.jenis_foto] || row.jenis_foto
			map[jenis] = row.foto
		}
	}
	return map
})
const semuaSlot = computed(() =>
	JENIS.map((jenis_foto) => ({ jenis_foto, foto: fotoByJenis.value[jenis_foto] || '' }))
)
const terisi = computed(() => semuaSlot.value.filter((s) => s.foto))
// Mode baca hanya menampilkan yang ada fotonya; mode isi menampilkan semua slot.
const barisTampil = computed(() => (props.editable ? semuaSlot.value : terisi.value))
const ringkasan = computed(() =>
	props.editable
		? `${terisi.value.length} dari ${JENIS.length} foto terisi`
		: `${terisi.value.length} foto`
)

function emitRows(map) {
	emit(
		'update:modelValue',
		JENIS.filter((jenis_foto) => map[jenis_foto]).map((jenis_foto) => ({
			jenis_foto,
			foto: map[jenis_foto],
		}))
	)
}

function lihat(slot) {
	if (slot.foto) openAttachment(slot.foto, slot.jenis_foto)
}

function pilih(jenis_foto) {
	if (uploading.value) return
	uploadingJenis.value = jenis_foto
	fileInput.value?.click()
}

function hapus(jenis_foto) {
	const map = { ...fotoByJenis.value }
	delete map[jenis_foto]
	emitRows(map)
}

async function onFileChange(e) {
	const file = e.target.files?.[0]
	e.target.value = ''
	const jenis_foto = uploadingJenis.value
	if (!file || !jenis_foto) {
		uploadingJenis.value = ''
		return
	}
	if (file.size > MAX_MB * 1024 * 1024) {
		uploadingJenis.value = ''
		emit('error', `Ukuran foto maksimal ${MAX_MB} MB.`)
		return
	}

	try {
		const file_url = await unggah(file)
		emitRows({ ...fotoByJenis.value, [jenis_foto]: file_url })
		emit('error', '')
	} catch (err) {
		emit('error', err?.message || 'Gagal mengunggah foto.')
	} finally {
		uploadingJenis.value = ''
	}
}

// Lewat method BSTK, bukan `upload_file` bawaan: endpoint bawaan menuntut izin
// write pada BSTK yang tidak dimiliki kolektor lapangan. Method ini memakai
// aturan Close yang sama, lalu melampirkan File-nya ke BSTK.
async function unggah(file) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('nomor_bstk', props.nomorBstk)
	const res = await fetch(
		'/api/method/juragan.collection.doctype.bstk.bstk.upload_foto_bstk',
		{
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		}
	)
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
	const file_url = json.message?.file_url
	if (!file_url) throw new Error('Upload foto gagal.')
	return file_url
}
</script>

<style scoped>
/* Pemicu lihat foto harus polos di SEMUA keadaan. Dua sumber abu-abu yang
   muncul saat ditekan: kilatan sentuh bawaan browser mobile
   (-webkit-tap-highlight-color) dan latar bawaan elemen <button> pada
