   sorotannya di sana memang diperlukan. */
.foto-lihat {
	-webkit-tap-highlight-color: transparent;
}
.foto-lihat:hover,
.foto-lihat:active,
.foto-lihat:focus,
.foto-lihat:focus-visible {
	background-color: transparent;
	outline: none;
	box-shadow: none;
}
</style>
